import imageManifest from "../../data/imageManifest.json";

/**
 * <picture> with AVIF and WebP sources generated by scripts/optimize-images.mjs.
 * `variant="cover"` uses the cropped card version when one exists.
 * Falls back to a plain <img> for images missing from the manifest.
 */
function ResponsiveImage({
  src,
  alt,
  variant,
  sizes = "100vw",
  loading = "lazy",
  fetchPriority,
  className,
}) {
  const entry =
    (variant && imageManifest[`${src}#${variant}`]) || imageManifest[src];

  if (!entry) {
    return <img className={className} src={src} alt={alt} loading={loading} />;
  }

  return (
    <picture>
      <source type="image/avif" srcSet={entry.avif} sizes={sizes} />
      <source type="image/webp" srcSet={entry.webp} sizes={sizes} />
      <img
        className={className}
        src={entry.fallback}
        alt={alt}
        width={entry.width}
        height={entry.height}
        loading={loading}
        decoding="async"
        fetchPriority={fetchPriority}
      />
    </picture>
  );
}

export default ResponsiveImage;
